class Solution {
    public int findContentChildren(int[] g, int[] s) {
        Arrays.sort(g);
        boolean[] used = new boolean[s.length];
        int content = 0;
        for (int need : g) {
            int best = -1;
            for (int j = 0; j < s.length; j++)
                if (!used[j] && s[j] >= need && (best == -1 || s[j] < s[best])) best = j;
            if (best != -1) { used[best] = true; content++; }
        }
        return content;
    }
}

