class Solution {
    public int numRescueBoats(int[] people, int limit) {
        Arrays.sort(people);
        int n = people.length, boats = 0;
        boolean[] seated = new boolean[n];
        for (int i = n - 1; i >= 0; i--) {
            if (seated[i]) continue;
            seated[i] = true;
            for (int j = i - 1; j >= 0; j--)
                if (!seated[j] && people[i] + people[j] <= limit) { seated[j] = true; break; }
            boats++;
        }
        return boats;
    }
}

