class Solution:
    def twoCitySchedCost(self, costs: List[List[int]]) -> int:
        m = len(costs)
        n = m // 2
        dp = [[inf] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = 0
        for i, (a_cost, b_cost) in enumerate(costs):
            for a in range(n + 1):
                if dp[i][a] == inf:
                    continue
                dp[i + 1][a] = min(dp[i + 1][a], dp[i][a] + b_cost)
                if a < n:
                    dp[i + 1][a + 1] = min(dp[i + 1][a + 1], dp[i][a] + a_cost)
        return dp[m][n]

