class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        n = len(senate)
        banned = [False] * n
        left = {'R': senate.count('R'), 'D': senate.count('D')}
        while True:
            for i in range(n):
                if banned[i]:
                    continue
                me = senate[i]
                other = 'D' if me == 'R' else 'R'
                if left[other] == 0:
                    return "Radiant" if me == 'R' else "Dire"
                j = (i + 1) % n
                while banned[j] or senate[j] == me:
                    j = (j + 1) % n
                banned[j] = True
                left[other] -= 1

