class Solution {
    public boolean canReach(String s, int minJump, int maxJump) {
        int n = s.length();
        boolean[] ok = new boolean[n];
        ok[0] = true;
        for (int i = 0; i < n; i++) {
            if (!ok[i]) continue;
            for (int j = i + minJump; j <= Math.min(i + maxJump, n - 1); j++)
                if (s.charAt(j) == '0') ok[j] = true;
        }
        return ok[n - 1];
    }
}

