            if (i - minJump >= 0 && ok[i - minJump]) reachable++;
            if (i - maxJump - 1 >= 0 && ok[i - maxJump - 1]) reachable--;
            ok[i] = reachable > 0 && s.charAt(i) == '0';
        }
        return ok[n - 1];
    }
}

